#include <vector>
#include <string>
using namespace std;

class Solution {
public:
    vector<int> goodIndices(string s, int k, int m) {
        int n = s.size();
        if (n < k) return {};
        vector<int> res;
        long long cur = 0;
        for (int i = 0; i < k; i++) {
            cur = (cur * 10 + (s[i] - '0')) % m;
        }
        if (cur == 0) res.push_back(0);
        long long power = 1;
        for (int i = 0; i < k - 1; i++) power = (power * 10) % m;
        for (int i = 1; i <= n - k; i++) {
            cur = (cur - (s[i - 1] - '0') * power) % m;
            if (cur < 0) cur += m;
            cur = (cur * 10 + (s[i + k - 1] - '0')) % m;
            if (cur == 0) res.push_back(i);
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public List<Integer> goodIndices(String s, int k, int m) {
        int n = s.length();
        List<Integer> res = new ArrayList<>();
        if (n < k) return res;
        long cur = 0;
        for (int i = 0; i < k; i++) {
            cur = (cur * 10 + (s.charAt(i) - '0')) % m;
        }
        if (cur == 0) res.add(0);
        long power = 1;
        for (int i = 0; i < k - 1; i++) power = (power * 10) % m;
        for (int i = 1; i <= n - k; i++) {
            cur = (cur - (s.charAt(i - 1) - '0') * power) % m;
            if (cur < 0) cur += m;
            cur = (cur * 10 + (s.charAt(i + k - 1) - '0')) % m;
            if (cur == 0) res.add(i);
        }
        return res;
    }
}

